# Stage 2: round-2 additions to the map (after MAP_PENDING): three rows asked by ROUND_LOG, closed families, Q12 closure.
import re, json
BASE = 'tmp/research-2026-11-16/'
L = open(BASE + 'push/c3-repair-map-theorem-a/OBSTRUCTION_MAP.stage1.md').read().split('\n')
log = []
def find(prefix):
    idx = [i for i, l in enumerate(L) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix, idx)
    return idx[0]
def last_row(letter):
    return [i for i, l in enumerate(L) if re.match(r'\| %s\d+ \|' % letter, l)][-1]
def ins_after(i, lines, tag, what):
    L[i+1:i+1] = lines; log.append((tag, what))

# --- header note
i = find('Path convention in tables:')
ins_after(i, ['', 'Update 2026-11-18 (`c3-repair-map-theorem-a`): the owed edits of `campaign/MAP_PENDING.md` (campaign round 1 `c1-*`, engine batch 1 `e1-*`) are applied; campaign round 2 (`c2-*`) is added as control WT (section 2), rows P41, P42, G25, Q21, Q22, the closure of row Q12, and updates to section 6 items 6, 7, 19, 20. Lanes `c1-*`, `c2-*`, `e1-*` each have a REFEREE.md (one internal referee unless a row says otherwise). The previous file is kept as `push/c3-repair-map-theorem-a/OBSTRUCTION_MAP.before.md`.'], 'R0', 'header update note')

# --- section 2: control WT
i = find('| B | Beurling zeta')
ins_after(i, ['| WT | window translate: zeta(s + i alpha_k), alpha_k = 2 pi k/log(T/2 pi) (lattice height translates of zeta); also L(s + i alpha, chi_5) read at height T/5 | Euler product with unimodular local parameters (completely multiplicative unimodular twist n^{-i alpha}); zeta\'s functional equation inside one window [T, T+H] up to a defect at most (abs(alpha) H/(2T) + alpha^2/(2T)) abs(zeta) (PROVED to leading order; the bound carries abs(zeta(1/2 + i(t + alpha))), which is not bounded in t); chi_5 case MEASURED (residual about 50/T). A window carries about 30 to 35 real conditions, a count that did not grow with T, against about sqrt(T)/log T free primes; a prescribed zero at 3/4 + i t_0 is feasible in cone slices at T = 1e5, 1e6 (MEASURED, float64 LP, one configuration at tolerance 1e-8) | the functional equation at all heights (its symmetry is s <-> 1 - s - 2 i alpha). Its own zeros are zeta\'s zeros translated: it is a control for rigidity, uniqueness and single-window statements, not a function with known off-line zeros | kills any argument whose functional-equation input is local to one window. With row Q21 (a unimodular twist is a torus rotation): a mechanism must read the angles t log p jointly and non-locally in height (Riemann-Siegel length, or all heights). Source: `c2-euler-cone-fe-rigidity` (refereed once, seven wording corrections) |'],
          'R2', 'section 2 control row WT (window translate)')
i = find('- Input level: every control lacks')
ins_after(i, ['- Controls added after the table was built. U (unimodular completely multiplicative twist; lacks the functional equation): at stage level it is a torus rotation of zeta\'s stage, and at fixed P a limit of height translates of it (row Q21). WT (table row above) is U with chi(n) = n^{-i alpha} at a lattice shift; it lacks the functional equation only non-locally in height, so in the input-level sets above "FE" means the functional equation at all heights. Finite modification (engine code FM): change of finitely many Euler factors, for example zeta(s)(1 - q^{b-s}) with zeros on Re s = b at s = b + 2 pi i k/log q, or the T-NR twin (which keeps the functional equation); it keeps every tail property of the prime sequence and every statement about primes p > P_0; it tests arguments whose hypotheses do not change when finitely many local factors change (elementary; stated by this repair lane, unrefereed). RZ_b = 1/zeta(s + 1 - b) is engine node `ctrl-rz-reciprocal-shift`.'],
          'R2b', 'section 2 note on U, WT, FM')
i = find('Q1. **Which step fails for each control?**')
assert 'DH, HEAT, TW+, TW-, EA, NR, B,' in L[i]
L[i] = L[i].replace('DH, HEAT, TW+, TW-, EA, NR, B,', 'DH, HEAT, TW+, TW-, EA, NR, B, WT (and U, the Liouville twist and a finite modification where formulable),'); log.append(('R2c', 'section 2 question Q1 lists WT'))

